package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerResponses(t *testing.T) {
	server := NewServer("", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name        string
		method      string
		target      string
		wantStatus  int
		wantAllow   string
		wantContent string
	}{
		{
			name:        "health",
			method:      http.MethodGet,
			target:      "/healthz",
			wantStatus:  http.StatusOK,
			wantContent: "ok",
		},
		{
			name:        "health rejects other methods",
			method:      http.MethodPost,
			target:      "/healthz",
			wantStatus:  http.StatusMethodNotAllowed,
			wantAllow:   http.MethodGet,
			wantContent: "method not allowed\n",
		},
		{
			name:        "list sorts by ID",
			method:      http.MethodGet,
			target:      "/accounts",
			wantStatus:  http.StatusOK,
			wantContent: "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true},{\"id\":\"b\",\"name\":\"Beta\",\"cents\":200,\"active\":false}]\n",
		},
		{
			name:        "list rejects invalid active",
			method:      http.MethodGet,
			target:      "/accounts?active=maybe",
			wantStatus:  http.StatusBadRequest,
			wantContent: "invalid active parameter\n",
		},
		{
			name:        "get account",
			method:      http.MethodGet,
			target:      "/accounts/a",
			wantStatus:  http.StatusOK,
			wantContent: "{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}\n",
		},
		{
			name:        "get unknown account",
			method:      http.MethodGet,
			target:      "/accounts/missing",
			wantStatus:  http.StatusNotFound,
			wantContent: "404 page not found\n",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			recorder := httptest.NewRecorder()
			request := httptest.NewRequest(tt.method, tt.target, nil)

			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != tt.wantStatus {
				t.Errorf("%s %s status = %d, want %d", tt.method, tt.target, recorder.Code, tt.wantStatus)
			}
			if got := recorder.Header().Get("Allow"); got != tt.wantAllow {
				t.Errorf("%s %s Allow = %q, want %q", tt.method, tt.target, got, tt.wantAllow)
			}
			if got := recorder.Body.String(); got != tt.wantContent {
				t.Errorf("%s %s body = %q, want %q", tt.method, tt.target, got, tt.wantContent)
			}
		})
	}
}

