package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestNewServerResponses(t *testing.T) {
	server := NewServer("127.0.0.1:8080", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
		{ID: "a", Name: "Duplicate", Cents: 999, Active: false},
	})

	tests := []struct {
		name        string
		method      string
		target      string
		wantStatus  int
		wantType    string
		wantHeaders map[string]string
		wantBody    string
	}{
		{name: "health", method: http.MethodGet, target: "/healthz", wantStatus: http.StatusOK, wantType: "text/plain; charset=utf-8", wantBody: "ok"},
		{name: "accounts", method: http.MethodGet, target: "/accounts", wantStatus: http.StatusOK, wantType: "application/json", wantBody: "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true},{\"id\":\"a\",\"name\":\"Duplicate\",\"cents\":999,\"active\":false},{\"id\":\"b\",\"name\":\"Beta\",\"cents\":200,\"active\":false}]\n"},
		{name: "active accounts", method: http.MethodGet, target: "/accounts?active=true", wantStatus: http.StatusOK, wantType: "application/json", wantBody: "[{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}]\n"},
		{name: "account", method: http.MethodGet, target: "/accounts/a", wantStatus: http.StatusOK, wantType: "application/json", wantBody: "{\"id\":\"a\",\"name\":\"Alpha\",\"cents\":100,\"active\":true}\n"},
		{name: "invalid filter", method: http.MethodGet, target: "/accounts?active=yes", wantStatus: http.StatusBadRequest, wantType: "text/plain; charset=utf-8", wantBody: "invalid query parameter: active\n"},
		{name: "unknown account", method: http.MethodGet, target: "/accounts/missing", wantStatus: http.StatusNotFound, wantType: "text/plain; charset=utf-8", wantBody: "404 page not found\n"},
		{name: "method not allowed", method: http.MethodPost, target: "/accounts", wantStatus: http.StatusMethodNotAllowed, wantType: "text/plain; charset=utf-8", wantHeaders: map[string]string{"Allow": http.MethodGet}, wantBody: "method not allowed\n"},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			request := httptest.NewRequest(test.method, test.target, nil)
			recorder := httptest.NewRecorder()

			server.Handler.ServeHTTP(recorder, request)

			if recorder.Code != test.wantStatus {
				t.Fatalf("status = %d, want %d", recorder.Code, test.wantStatus)
			}
			if got := recorder.Header().Get("Content-Type"); got != test.wantType {
				t.Fatalf("content type = %q, want %q", got, test.wantType)
			}
			for header, want := range test.wantHeaders {
				if got := recorder.Header().Get(header); got != want {
					t.Fatalf("%s = %q, want %q", header, got, want)
				}
			}
			if got := recorder.Body.String(); got != test.wantBody {
				t.Fatalf("body = %q, want %q", got, test.wantBody)
			}
		})
	}
}

