package gateway

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestServerResponses(t *testing.T) {
	server := NewServer(":0", []Account{
		{ID: "b", Name: "Beta", Cents: 200, Active: false},
		{ID: "a", Name: "Alpha", Cents: 100, Active: true},
	})

	tests := []struct {
		name       string
		method     string
		target     string
		wantStatus int
		wantType   string
		wantBody   string
	}{
		{
			name:       "health",
			method:     http.MethodGet,
			target:     "/healthz",
			wantStatus: http.StatusOK,
			wantBody:   "ok",
		},
		{
			name:       "list is sorted",
			method:     http.MethodGet,
			target:     "/accounts",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `[{"id":"a","name":"Alpha","cents":100,"active":true},{"id":"b","name":"Beta","cents":200,"active":false}]` + "\n",
		},
		{
			name:       "active filter",
			method:     http.MethodGet,
			target:     "/accounts?active=false",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `[{"id":"b","name":"Beta","cents":200,"active":false}]` + "\n",
		},
		{
			name:       "invalid active filter",
			method:     http.MethodGet,
			target:     "/accounts?active=maybe",
			wantStatus: http.StatusBadRequest,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "invalid query parameter \"active\"\n",
		},
		{
			name:       "account",
			method:     http.MethodGet,
			target:     "/accounts/a",
			wantStatus: http.StatusOK,
			wantType:   "application/json",
			wantBody:   `{"id":"a","name":"Alpha","cents":100,"active":true}` + "\n",
		},
		{
			name:       "unknown account",
			method:     http.MethodGet,
			target:     "/accounts/missing",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "unknown path",
			method:     http.MethodGet,
			target:     "/missing",
			wantStatus: http.StatusNotFound,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "404 page not found\n",
		},
		{
			name:       "known path wrong method",
			method:     http.MethodPost,
			target:     "/accounts",
			wantStatus: http.StatusMethodNotAllowed,
			wantType:   "text/plain; charset=utf-8",
			wantBody:   "Method Not Allowed\n",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			record := httptest.NewRecorder()
			request := httptest.NewRequest(test.method, test.target, nil)
			server.Handler.ServeHTTP(record, request)

			if record.Code != test.wantStatus {
				t.Fatalf("status = %d, want %d", record.Code, test.wantStatus)
			}
			if got := record.Header().Get("Content-Type"); got != test.wantType {
				t.Fatalf("Content-Type = %q, want %q", got, test.wantType)
			}
			if record.Body.String() != test.wantBody {
				t.Fatalf("body = %q, want %q", record.Body.String(), test.wantBody)
			}
		})
	}
}

